using System.Collections;
using LittleLeo;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "EquivalentConjurationAction", menuName = "Data/Battle/Battle Actions/Orion/EquivalentConjuration Action")]
public class EquivalentConjurationAction : BattleAction
{
	public override void CastAmount(int amount, GameObject source)
	{
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(CastCoroutine(ReferenceSingleton<BattleHandler>.Instance.GetOrionAstrarium(source).ActivateAllStarsAbilitiesCoroutine(amount), source));
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
	}

	private IEnumerator CastCoroutine(IEnumerator coroutineToUse, GameObject source)
	{
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
		yield return ReferenceSingleton<CoroutineHandler>.Instance.Run(coroutineToUse);
	}
}
